mapper.select:
SELECT

FROM task
WHERE project_id = #{project_id}
  AND task_id = #{task_id}

mapper.update:
UPDATE task
SET
    assignee_id = #{assignee_id},
    task_name = #{task_name},
    description = #{description},
    due_date = #{due_date}
WHERE project_id = #{project_id}
  AND task_id = #{task_id}

mapper.delete:
DELETE FROM task
WHERE project_id = #{project_id}
  AND task_id = #{task_id}

mapper.update:
UPDATE task
SET
    status = 'REJECTED',
    reject_reason = #{reject_reason}
WHERE project_id = #{project_id}
  AND task_id = #{task_id}
  AND status = 'REVIEW'

UPDATE task
SET status = 'ONGOING'
WHERE project_id = #{project_id}
  AND task_id = #{task_id}
  AND assignee_id = #{assignee_id}
  AND status = 'REJECTED'
